# Servidor HTTP nativo em Python 3 com zero dependências externas
import http.server, json

def handle_sync_event(session, event):
    """Distribui eventos em LAN com latência sub-50ms"""
    session.state['currentSlide'] = event['slide']
    session.broadcast(event)
    return {'status': 'ok', 'rtt_ms': 1.8}

if __name__ == '__main__':
    print('SlideMeshLive rodando em http://localhost:8080')
